import {createPush,pushSupport} from './modules/push.js';
import {clientReport,internalReport} from './modules/reports.js';
import {api} from './care-backend.js';
import {escapeHTML as e,labels,dayKey,formatDate as dt,conflicts,dateRange,dashboard,isoDate} from './modules/domain.js';
import {navIcon} from './modules/icons.js';
const app=document.querySelector('#app');
const push=createPush(api);let pushState=null,pushError='',pushLoading=false;
let w=null,route=location.hash==='#notifications'?'notifications':'home',selected=null,filterSite='',calendar=dayKey(),calendarMode='week',busy=false,refreshing=false,lastSync=null;
const clientPortal=new URLSearchParams(location.search).get('portal')==='client'||location.pathname.endsWith('/client.html');
let recovery=new URLSearchParams(location.search).has('recovery')||/type=(recovery|invite)/.test(location.hash);
const isQ=()=>['qg_admin','qg_manager'].includes(w?.profile.role);
const isC=()=>w?.profile.role==='client';
const by=(list,id)=>list.find(x=>x.id===id);
const siteName=id=>by(w.sites,id)?.name||'Site';
const name=id=>by(w.people,id)?.full_name||'Agent';
const badge=s=>`<span class="status ${['completed','validated','resolved','published'].includes(s)?'green':s==='in_progress'?'blue':['failed','refused','cancelled'].includes(s)?'red':'gray'}">${e(labels[s]||s)}</span>`;
const button=(label,action,id='',primary=false)=>`<button class="btn ${primary?'primary':''}" data-action="${action}" data-id="${e(id)}">${label}</button>`;
const empty=(text='Aucun élément pour le moment')=>`<div class="empty-state">${e(text)}</div>`;
function toast(message,error=false){const n=document.createElement('div');n.className=`toast ${error?'error':''}`;n.textContent=message;document.querySelector('#toast-root').append(n);setTimeout(()=>n.remove(),7000);}
const field=(name,label,value='',type='text',required=false)=>`<div class="field"><label for="f-${name}">${e(label)}</label><input class="input" id="f-${name}" name="${name}" type="${type}" value="${e(value)}" ${required?'required':''} ${type==='text'?'maxlength="500"':''}></div>`;
const area=(name,label,value='')=>`<div class="field"><label for="f-${name}">${e(label)}</label><textarea class="input" id="f-${name}" name="${name}" maxlength="5000">${e(value)}</textarea></div>`;
const select=(name,label,items,value='',blank=false)=>`<div class="field"><label for="f-${name}">${e(label)}</label><select class="input" id="f-${name}" name="${name}" ${blank?'':'required'}>${blank?'<option value="">Aucun</option>':''}${items.map(x=>`<option value="${e(x.id)}" ${x.id===value?'selected':''}>${e(x.name)}</option>`).join('')}</select></div>`;
const check=(name,label,value=false)=>`<label class="check-line"><input type="checkbox" name="${name}" ${value?'checked':''}> ${e(label)}</label>`;
const opts=obj=>Object.entries(obj).map(([id,name])=>({id,name}));
const categories={cleaning:'Nettoyage',maintenance:'Maintenance légère',repair:'Petit bricolage',other:'Autre'};
let restoreFocus=null;
function modal(title,html,submit){closeModal();restoreFocus=document.activeElement;const d=document.createElement('dialog');d.id='care-dialog';d.innerHTML=`<form id="modal-form"><div class="modal-head"><h2>${e(title)}</h2><button class="icon-btn" type="button" data-action="close" aria-label="Fermer">×</button></div><div class="form-content">${html}</div><p class="form-error" role="alert"></p>${submit?'<button class="btn primary full" type="submit">Enregistrer</button>':''}</form>`;document.body.append(d);d.showModal();d.addEventListener('cancel',ev=>{if(busy)ev.preventDefault();else closeModal();});d.querySelectorAll('button:not([type])').forEach(b=>b.type='button');if(submit)d.querySelector('form').onsubmit=async ev=>{ev.preventDefault();if(busy)return;const form=ev.target;const submitButton=form.querySelector('[type=submit]');busy=true;submitButton.disabled=true;submitButton.textContent='Enregistrement…';form.querySelector('.form-error').textContent='';try{await submit(new FormData(form),form);closeModal();await refresh();}catch(err){form.querySelector('.form-error').textContent=err.message;submitButton.disabled=false;submitButton.textContent='Réessayer';}finally{busy=false}};}
function closeModal(){const d=document.querySelector('#care-dialog');if(d){d.close();d.remove();restoreFocus?.focus?.();}}
function login(message=''){app.innerHTML=`<main class="login-screen ${clientPortal?'portal-client':''}"><div class="login-wrap auth-wrap"><header class="login-brand"><img class="login-logo" src="assets/logo-azzera.png" alt="Azzera Services+"><div class="product-name">AZZERA <span>CARE${clientPortal?' CLIENT':''}</span></div><p class="login-tagline">${clientPortal?'Vos prestations, vos comptes-rendus et vos demandes':'Votre espace professionnel · QG et agents terrain'}</p></header><section class="auth-card"><div class="eyebrow">${clientPortal?'Portail client':'Portail professionnel'}</div><h1>${recovery?'Définir votre mot de passe':'Bienvenue sur Care'}</h1>${!api.configured?'<p>Connexion non configurée. Renseigne config.js en suivant INSTALLATION_SUPABASE.md.</p>':`<form id="login-form">${recovery?'':field('email','Adresse e-mail','','email',true)}${field('password',recovery?'Nouveau mot de passe (12 caractères minimum)':'Mot de passe','','password',true)}<p class="form-error" role="alert">${e(message)}</p><button class="btn primary full" type="submit">${recovery?'Enregistrer le mot de passe':'Se connecter'}</button>${recovery?'':button('Mot de passe oublié','reset')}</form>`}<a class="portal-switch" href="${clientPortal?'./index.html?portal=pro':'./client.html?portal=client'}">${clientPortal?'Accès QG et agents →':'Accès Azzera Care Client →'}</a></section></div></main>`;
const f=document.querySelector('#login-form');if(f)f.onsubmit=async ev=>{ev.preventDefault();const values=new FormData(f),b=f.querySelector('[type=submit]');b.disabled=true;try{if(recovery){if(values.get('password').length<12)throw new Error('Choisis au moins 12 caractères.');await api.password(values.get('password'));recovery=false;history.replaceState(null,'',location.pathname+(clientPortal?'?portal=client':''));}else await api.signIn(values.get('email'),values.get('password'));await enter();}catch(err){login(err.message)}};}
async function enter(){w=await api.snapshot();if((w.profile.role==='client')!==clientPortal){await api.signOut();w=null;throw new Error('Ce compte doit utiliser l’autre portail. Utilise le lien sous le formulaire.');}pushState=null;pushError='';lastSync=new Date();render();push.reconcile().catch(()=>{});}
async function refresh(){if(!w||refreshing)return;refreshing=true;try{const next=await api.snapshot();const changed=JSON.stringify(w)!==JSON.stringify(next);w=next;lastSync=new Date();if(!document.querySelector('dialog')){if(changed)render();const sync=document.querySelector('.sync-state');if(sync)sync.textContent='Actualisé à '+lastSync.toLocaleTimeString('fr-FR')+' · '+(navigator.onLine?'Connexion disponible':'Hors connexion — actions indisponibles');}}catch(err){if(/désactivé|autorisé|JWT|expired/i.test(err.message)){w=null;closeNavigation();closeModal();login(err.message);}else toast('Actualisation impossible : '+err.message,true);}finally{refreshing=false}}
function nav(){return isQ()?[['home','Accueil'],['planning','Planning'],['interventions','Interventions'],['clients','Clients'],['sites','Sites'],['team','Équipe et accès'],['requests','Demandes'],['issues','Signalements'],['quality','Qualité'],['docs','Documents'],['logbook','Historique'],['notifications','Notifications'],['profile','Mon compte']]:isC()?[['home','Accueil'],['sites','Mes établissements'],['interventions','Prestations'],['requests','Demandes'],['docs','Documents'],['notifications','Notifications'],['profile','Mon compte']]:[['home','Accueil'],['planning','Planning'],['interventions','Mes missions'],['issues','Signalements'],['docs','Documents'],['notifications','Notifications'],['profile','Mon compte']];}
function closeNavigation(){const d=document.querySelector('#care-navigation');if(d){d.close();d.remove();document.querySelector('[data-action="menu"]')?.focus();}}
function openNavigation(){
 if(document.querySelector('#care-navigation'))return;
 const d=document.createElement('dialog');d.id='care-navigation';d.className='care-navigation-dialog'+(isC()?' portal-client':'');d.setAttribute('aria-labelledby','navigation-title');
 d.innerHTML=`<header class="navigation-heading"><div><p>AZZERA CARE</p><h2 id="navigation-title">Votre espace ${isQ()?'QG':isC()?'client':'agent'}</h2></div><button class="care-icon-button" data-action="close-menu" aria-label="Fermer le menu">${navIcon('close')}</button></header><nav aria-label="Navigation principale">${nav().map(([r,l])=>`<button data-route="${r}" class="care-menu-link ${r===route?'active':''}" ${r===route?'aria-current="page"':''}>${navIcon(r)}<span>${e(l)}</span><span aria-hidden="true">→</span></button>`).join('')}</nav><footer><strong>${e(w.profile.full_name)}</strong><button class="care-menu-link" data-action="logout">${navIcon('logout')}<span>Se déconnecter</span></button></footer>`;
 document.body.append(d);d.addEventListener('cancel',ev=>{ev.preventDefault();closeNavigation()});d.addEventListener('click',ev=>{if(ev.target===d){const r=d.getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)closeNavigation()}});d.showModal();
}
function agentDock(){
 if(isQ()||isC()||route!=='detail')return '';
 const i=by(w.interventions,selected),mine=w.assignments.find(a=>a.intervention_id===selected&&a.agent_id===w.profile.id);
 if(!i||!mine||mine.ended_at||['completed','validated','cancelled','impossible'].includes(i.status))return '';
 const tasks=w.tasks.filter(t=>t.intervention_id===i.id);
 return `<section class="care-agent-dock" aria-label="Actions de mon intervention"><div class="care-dock-progress"><strong>${mine.started_at?'Intervention en cours':'Prêt à commencer'}</strong><button class="care-task-shortcut" data-action="show-tasks">Tâches ${tasks.filter(t=>t.completed).length}/${tasks.length} ↓</button></div>${mine.started_at?`<div class="care-dock-tools">${button(navIcon('photo')+'<span>Photo</span>','photo',i.id)}${button(navIcon('logbook')+'<span>Observation</span>','note',i.id)}${button('<span>Terminer</span>'+navIcon('check'),'finish',i.id,true)}</div>`:button('Démarrer mon intervention','start',i.id,true)}</section>`;
}
function shell(content,title,actions=''){
 const items=nav(),roleName=isC()?'CLIENT':isQ()?'QG SERVICES+':'AGENT TERRAIN';
 const quick=isQ()?['home','planning','interventions','requests']:isC()?['home','sites','interventions','requests']:['home','planning','interventions'];
 const dock=agentDock();
 return `<div class="v3-shell ${isC()?'portal-client':isQ()?'portal-qg':'portal-agent'} ${isQ()?'':'mobile-role'} ${dock?'with-agent-dock':''}"><aside class="sidebar"><div class="sidebar-brand"><img src="assets/logo-azzera.png" alt="Azzera Services+"><div><strong>AZZERA <span>CARE</span></strong><small>${roleName}</small></div></div><nav class="side-nav" aria-label="Navigation principale">${items.map(([r,l])=>`<button class="side-link ${r===route?'active':''}" data-route="${r}" ${r===route?'aria-current="page"':''}>${navIcon(r)}${e(l)}</button>`).join('')}</nav><div class="sidebar-footer"><strong>${e(w.profile.full_name)}</strong><button class="side-link" data-action="logout">Se déconnecter</button></div></aside><main class="v3-main"><header class="v3-top"><button class="care-header-brand" data-route="home" aria-label="Azzera Care — Accueil"><img src="assets/logo-azzera.png" alt=""><span><strong>AZZERA <b>CARE</b></strong><small>${roleName}</small></span></button><div class="care-header-actions"><button class="care-icon-button" data-action="refresh" aria-label="Actualiser" title="Actualiser"><svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M20 7v5h-5M4 17v-5h5M19 11a7 7 0 0 0-12-5L4 9m16 6-3 3a7 7 0 0 1-12-5"/></svg></button><button class="care-icon-button mobile-menu-toggle" data-action="menu" aria-label="Ouvrir le menu" aria-haspopup="dialog">${navIcon('menu')}</button><span class="desktop-logout">${button('Déconnexion','logout')}</span></div></header><header class="page-head"><div><div class="eyebrow">${isC()?'Votre espace Azzera Services+':isQ()?'Pilotage des prestations':'Sur le terrain'}</div><h1>${e(title)}</h1><p class="sync-state">Actualisé à ${lastSync?.toLocaleTimeString('fr-FR')||'—'} · ${navigator.onLine?'Connexion disponible':'Hors connexion — actions indisponibles'}</p></div><div class="head-actions">${actions}</div></header>${content}</main>${dock}<nav class="v3-bottom" aria-label="Accès rapides">${items.filter(([r])=>quick.includes(r)).map(([r,l])=>`<button data-route="${r}" class="${r===route||r==='interventions'&&route==='detail'?'active':''}" ${r===route?'aria-current="page"':''}>${navIcon(r)}<span>${e(({sites:"Sites",interventions:isC()?"Prestations":isQ()?"Missions":"Mes missions"})[r]||l)}</span></button>`).join('')}<button data-action="menu" aria-label="Ouvrir le menu complet">${navIcon('menu')}<span>Menu</span></button></nav></div>`;
}

function missionCards(list){return list.length?`<div class="mission-list">${list.map(i=>`<button class="mission-card" data-action="detail" data-id="${e(i.id)}"><div><span class="eyebrow">${e(siteName(i.site_id))}</span><h3>${e(i.title)}</h3><p>${e(dt(i.starts_at))} → ${e(dt(i.ends_at))}</p><small>${isC()?`${i.finished_agents??0}/${i.total_agents??'—'} participation(s) terminée(s)` : e(w.assignments.filter(a=>a.intervention_id===i.id).map(a=>name(a.agent_id)).join(' · '))}</small></div>${badge(i.status)}<span aria-hidden="true">→</span></button>`).join('')}</div>`:empty('Aucune intervention dans cette sélection');}
function home(){const m=dashboard(w);const metrics=isQ()?[['Aujourd’hui',m.today],['En cours',m.active],['Terminées ce jour',m.completed],['À venir',m.upcoming],['Agents mobilisés',m.agents],['Signalements ouverts',m.issues],['Demandes à traiter',m.requests],['Publications en échec',w.interventions.filter(i=>i.publication_state==='failed').length]]:isC()?[['Établissements',w.sites.length],['Comptes-rendus',w.reports.length],['Demandes en cours',m.requests]]:[['Missions du jour',m.today],['Mes participations en cours',w.assignments.filter(a=>a.agent_id===w.profile.id&&a.started_at&&!a.ended_at).length],['À venir',m.upcoming]];
const ordered=[...w.interventions].sort((a,b)=>new Date(a.starts_at)-new Date(b.starts_at));
const live=ordered.filter(i=>i.status==='in_progress');
const next=ordered.filter(i=>new Date(i.starts_at)>=new Date()&&['planned','upcoming'].includes(i.status)).slice(0,5);
const done=ordered.filter(i=>['completed','validated'].includes(i.status)).reverse().slice(0,5);
const agent=!isQ()&&!isC();
const assigned=ordered.filter(i=>w.assignments.some(a=>a.intervention_id===i.id&&a.agent_id===w.profile.id&&!a.ended_at)&&!['completed','validated','cancelled','impossible'].includes(i.status));
const focus=assigned.find(i=>w.assignments.some(a=>a.intervention_id===i.id&&a.agent_id===w.profile.id&&a.started_at&&!a.ended_at))||assigned[0];
const latest=[...w.reports].sort((a,b)=>new Date(b.published_at)-new Date(a.published_at)).find(r=>w.interventions.some(i=>i.id===r.intervention_id));
const hero=agent?`<section class="v3-hero agent-focus"><div class="eyebrow">${focus?'Votre priorité':'Votre journée'}</div><h2>${focus?e(focus.title):'Tout est à jour'}</h2><p>${focus?e(siteName(focus.site_id))+' · '+e(dt(focus.starts_at)):'Les prochaines missions affectées par le QG apparaîtront ici'}</p>${focus?button('Ouvrir ma mission →','detail',focus.id,true):'<button class="btn primary" data-route="planning">Consulter mon planning</button>'}<div class="agent-steps"><span>01 · Démarrer</span><span>02 · Réaliser les tâches</span><span>03 · Terminer</span></div></section>`:`<section class="v3-hero"><div class="eyebrow">${isC()?'AZZERA SERVICES+ · ESPACE CLIENT':'Votre journée en un regard'}</div><h2>${isC()?'Le soin de vos espaces,<br>en toute clarté':'Une journée bien organisée'}</h2><p>${isC()?'Vos établissements, le suivi des prestations et les attentions de nos équipes réunis dans votre espace':'Missions, preuves et suivi réunis dans votre espace'}</p>${isC()?`<div class="hero-actions">${latest?button('Consulter le dernier compte-rendu','report',latest.intervention_id,true):'<button class="btn primary" data-route="interventions">Découvrir mes prestations</button>'}<button class="btn" data-route="requests">Mes demandes →</button></div><span class="hero-signature" aria-hidden="true">CARE</span>`:''}</section>`;
return shell(`${hero}<section class="metrics">${metrics.map(([l,v])=>`<div class="card"><span>${e(l)}</span><strong>${v}</strong></div>`).join('')}</section><section class="section"><h2>${agent?'Mes missions en cours':'En cours'}</h2>${missionCards(agent?live.filter(i=>assigned.some(a=>a.id===i.id)):live)}</section><section class="section"><h2>Prochaines interventions</h2>${missionCards(next)}</section><section class="section"><h2>Dernières interventions terminées</h2>${missionCards(done)}</section>`,'Bonjour '+w.profile.full_name.split(' ')[0],isQ()?button('＋ Intervention','new-intervention','',true):isC()?button('＋ Demande','new-request','',true):'');}

function planning(){const dates=dateRange(calendar,calendarMode),pairs=conflicts(w.interventions,w.assignments);return shell(`<div class="toolbar">${button('←','prev-date')}<input aria-label="Date du planning" id="calendar-date" class="input" type="date" value="${calendar}">${button('→','next-date')}<select id="calendar-mode" class="input" aria-label="Vue du planning"><option value="day" ${calendarMode==='day'?'selected':''}>Jour</option><option value="week" ${calendarMode==='week'?'selected':''}>Semaine</option></select>${button('Aujourd’hui','today')}</div>${pairs.length?`<div class="notice warning">${pairs.length} chevauchement(s) d’affectation détecté(s). Les missions concernées sont signalées ci-dessous.</div>`:''}<div class="week-grid">${dates.map(d=>`<section class="day-column"><h2>${e(new Date(d+'T12:00Z').toLocaleDateString('fr-FR',{weekday:'short',day:'numeric',month:'short'}))}</h2>${w.interventions.filter(i=>dayKey(i.starts_at)===d).map(i=>`<div>${pairs.some(p=>p.a===i.id||p.b===i.id)?'<p class="warning">⚠ Chevauchement</p>':''}${missionCards([i])}</div>`).join('')||empty('Aucune mission')}</section>`).join('')}</div>`,'Planning',isQ()?button('＋ Intervention','new-intervention','',true):'');}
function interventions(){return shell(`<div class="toolbar">${select('filter-site','Site',w.sites,filterSite,true)}</div>${missionCards(w.interventions.filter(i=>!filterSite||i.site_id===filterSite))}`,'Interventions',isQ()?button('＋ Intervention','new-intervention','',true):'');}
function photos(list){return list.length?`<div class="v3-photos">${list.map(p=>`<figure><button data-action="photo-view" data-id="${e(p.id)}"><img data-path="${e(p.storage_path)}" alt="${e(({before:'Avant',after:'Après',issue:'Anomalie',general:'Autre preuve'})[p.category]||'Photo')}" loading="lazy"></button><figcaption>${e(({before:'Avant',after:'Après',issue:'Anomalie',general:'Autre preuve'})[p.category]||'Photo')} · ${e(dt(p.captured_at))}${!isC()&&p.uploaded_by?' · '+e(name(p.uploaded_by)):''}<p>${e(p.caption)}</p>${isQ()&&p.intervention_id?button(p.publishable?'Retirer du client':'Autoriser pour le client','photo-permission',p.id):''}</figcaption></figure>`).join('')}</div>`:empty('Aucune photo enregistrée');}
function detail(){const i=by(w.interventions,selected);if(!i)return shell(empty('Intervention inaccessible'),'Intervention');const s=by(w.sites,i.site_id),team=w.assignments.filter(a=>a.intervention_id===i.id),mine=team.find(a=>a.agent_id===w.profile.id),tasks=w.tasks.filter(t=>t.intervention_id===i.id),ph=w.photos.filter(p=>p.intervention_id===i.id),logs=w.logs.filter(l=>l.intervention_id===i.id);const report=w.reports.find(r=>r.intervention_id===i.id);
return shell(`<section class="card mission-summary">${badge(i.status)}<h2>${e(i.title)}</h2><p>${e(siteName(i.site_id))} · ${e(s?.address)}</p><p>${e(dt(i.starts_at))} → ${e(dt(i.ends_at))}</p>${!isC()?`<p><b>Prestation :</b> ${e(categories[i.service_type]||i.service_type)}</p><p class="prewrap">${e(i.description)}</p><details class="mission-instructions" ${isQ()||!mine?.started_at?'open':''}><summary>Consignes et accès au site</summary><p class="prewrap">${e(i.instructions)}\n${e(s?.general_instructions)}\n${e(s?.access_notes)}</p></details>${isQ()?`<details><summary>Notes internes QG</summary><p class="prewrap">${e(i.internal_notes)}</p></details>`:''}`:''}${report?`<p>Compte-rendu publié · révision ${report.revision} · ${e(dt(report.published_at))}</p>${button('Ouvrir le compte-rendu A4','report',i.id,true)}`:isC()?'<p>Le compte-rendu sera disponible après la première fin de participation.</p>':''}${i.publication_state==='failed'?`<div class="notice warning">La dernière publication a échoué. Le client conserve uniquement le dernier compte-rendu confirmé.${button('Reprendre la publication','retry',i.id)}</div>`:''}</section>
${!isC()?`<section class="section card participation-section"><details ${isQ()?'open':''}><summary>Participations individuelles</summary>${team.map(a=>`<div class="list-row"><strong>${e(name(a.agent_id))}</strong><span>Début : ${e(dt(a.started_at))}<br>Fin : ${e(dt(a.ended_at))}${a.ended_at?`<br>Durée : ${Math.round((new Date(a.ended_at)-new Date(a.started_at))/60000)} min`:''}</span></div>`).join('')}</details>${mine?`<div class="mission-actions">${!mine.started_at?button('DÉMARRER MON INTERVENTION','start',i.id,true):!mine.ended_at?button('TERMINER MON INTERVENTION','finish',i.id,true):'<p>Votre participation est terminée</p>'}</div>`:''}</section>`:''}
<section class="section card" id="mission-checklist"><div class="section-title"><h2>${!isQ()&&!isC()?'Mes tâches':'Checklist'}</h2><span class="task-count">${tasks.filter(t=>t.completed).length} / ${tasks.length}</span></div>${tasks.length?`<progress class="task-progress" max="${tasks.length}" value="${tasks.filter(t=>t.completed).length}" aria-label="Tâches réalisées"></progress>`:''}${tasks.map(t=>`<div class="task-row ${t.completed?'is-complete':''}"><span class="task-indicator">${t.completed?'✓':'○'}</span><div><strong>${e(t.label)}</strong><p>${t.required?'Obligatoire':'Facultative'}${!isC()?' · '+e({none:'Validation simple',photo:'Photo obligatoire',comment:'Commentaire obligatoire'}[t.proof_required]||''):''}</p>${!isC()&&t.completed?`<small>${e(name(t.completed_by))} · ${e(dt(t.completed_at))}</small>`:''}</div>${!isC()&&(isQ()||mine?.started_at&&!mine.ended_at)&&!['completed','validated','cancelled'].includes(i.status)?button(t.completed?'Retirer':'Valider','task',t.id):''}</div>`).join('')||empty('Aucune tâche définie')}</section>
<section class="section card"><div class="section-title"><h2>Photos et preuves</h2>${!isC()&&(isQ()||mine?.started_at&&!mine.ended_at)?button('＋ Photo','photo',i.id):''}</div>${photos(ph)}</section>
${isC()?`<section class="section card"><h2>Observations publiées</h2><p class="prewrap">${e(i.client_summary||'Aucune observation publiée')}</p></section>`:`<section class="section card"><div class="section-title"><h2>Main courante</h2><div class="head-actions">${isQ()||mine?.started_at&&!mine.ended_at?button('Observation','note',i.id)+button('Signalement','issue',i.id):''}</div></div>${logs.map(l=>`<div class="timeline-item"><time>${e(dt(l.created_at))} · ${e(name(l.author_id))}</time><h3>${e(l.title)}</h3><p class="prewrap">${e(l.details)}</p></div>`).join('')||empty()}</section>`}`,'Fiche intervention',isQ()?button('Exporter la main courante','internal-report',i.id)+button('Modifier le planning','edit-intervention',i.id)+button('Correction exceptionnelle','correct',i.id)+(['planned','upcoming'].includes(i.status)?button('Annuler','cancel',i.id):''):'');}
function clients(){return shell(`<div class="record-grid">${w.clients.map(c=>`<article class="card"><h2>${e(c.name)}</h2><p>${e(c.email)} · ${e(c.phone)}</p><p class="prewrap">${e(c.contacts)}</p><p>${c.active?'Accès autorisés':'Accès client désactivés'}</p>${button('Modifier','client',c.id)}${button('Sites et historique','client-sites',c.id)}</article>`).join('')||empty()}</div>`,'Clients',button('＋ Client','client','',true));}
function sites(){return shell(`<div class="record-grid">${w.sites.map(s=>`<article class="card"><div class="eyebrow">${e(by(w.clients,s.client_id)?.name)}</div><h2>${e(s.name)}</h2><p>${e(s.address)}</p><p class="prewrap">${e(s.contacts)}</p>${button('Historique et prestations','site-history',s.id)}${isQ()?button('Modifier','site',s.id):''}</article>`).join('')||empty()}</div>`,'Établissements',isQ()?button('＋ Site','site','',true):'');}
function people(){return shell(`<div class="record-grid">${w.people.map(p=>`<article class="card"><h2>${e(p.full_name)}</h2><p>${e(p.role)} · ${p.active?'Actif':'Désactivé'}</p><p>${e(p.phone)}</p><p>${w.assignments.filter(a=>a.agent_id===p.id).length} affectation(s)</p>${p.id!==w.profile.id&&p.role!=='qg_admin'?button('Gérer le compte','profile-edit',p.id):''}${button('Affectations','agent-history',p.id)}</article>`).join('')}</div>`,'Équipe et accès',button('Créer un accès','create-user','',true)+button('Inviter par e-mail','invite'));}
function requests(){return shell(`<div class="record-grid">${w.requests.map(r=>`<article class="card">${badge(r.request_state)}<h2>${e(r.title)}</h2><p>${e(siteName(r.site_id))} · ${e(dt(r.created_at))}</p><p>Catégorie : ${e(categories[r.category]||r.category)} · Souhait : ${e(r.desired_date||'Non précisé')}</p><p class="prewrap">${e(r.details)}</p>${(w.requestPhotos||[]).filter(p=>p.client_request_id===r.id).map(p=>button('Voir la pièce jointe','request-photo',p.id)).join('')}${r.intervention_id?`<p>Intervention liée${r.accepted_at?' · Acceptée le '+e(dt(r.accepted_at)):''}</p>${by(w.interventions,r.intervention_id)?button('Ouvrir l’intervention','detail',r.intervention_id):''}`:''}${isQ()?(!r.intervention_id&&['new','in_progress'].includes(r.request_state)?button('Accepter et préparer l’intervention','request-accept',r.id,true):'')+button('Traiter','request-state',r.id):button('Ajouter une photo','request-upload',r.id)}</article>`).join('')||empty()}</div>`,'Demandes clients',isC()?button('＋ Demande','new-request','',true):'');}
function issues(){return shell(`<div class="record-grid">${w.issues.map(i=>`<article class="card">${badge(i.status)}<h2>${e(i.title)}</h2><p>${e(siteName(i.site_id))} · ${e(i.category)} · ${e(i.priority)}</p><p class="prewrap">${e(i.details)}</p>${button('Mission','detail',i.intervention_id)}${isQ()?button('État du signalement','issue-state',i.id):''}</article>`).join('')||empty()}</div>`,'Signalements');}
function docs(){return shell(`<div class="record-grid">${w.documents.map(d=>`<article class="card"><h2>${e(d.title)}</h2><p>${e(siteName(d.site_id))} · ${e(d.visibility)}</p>${button('Ouvrir','document-view',d.id)}</article>`).join('')||empty()}</div><section class="section"><h2>Comptes-rendus d’intervention</h2>${missionCards(w.interventions.filter(i=>w.reports.some(r=>r.intervention_id===i.id)))}</section>`,'Documents et rapports',isQ()?button('＋ Document','document','',true):'');}
function quality(){return shell(`<div class="record-grid">${w.quality.map(c=>`<article class="card"><h2>${e(siteName(c.site_id))}</h2><p>${e(c.result)} · ${e(dt(c.created_at))}</p><p class="prewrap">${e(c.observations)}</p></article>`).join('')||empty()}</div>`,'Contrôles qualité',button('＋ Contrôle','quality','',true));}
function logs(){return shell(`<section class="card">${w.audit.map(a=>`<div class="list-row"><div><strong>${e(a.kind)}</strong><p>${e(dt(a.created_at))} · ${e(name(a.actor))}</p><details><summary>Détails de la modification</summary><pre>${e(JSON.stringify(a.details,null,2))}</pre></details></div></div>`).join('')||empty()}</section>`,'Historique des opérations');}
async function loadPushState(){if(pushLoading||!w)return;pushLoading=true;const user=w.profile.id;try{const state=await push.status();if(w?.profile.id===user){pushState=state;pushError='';}}catch(err){if(w?.profile.id===user)pushError=err.message;}finally{pushLoading=false;if(w?.profile.id===user&&route==='notifications')render();}}
function notifications(){const unsupported=pushSupport(),stats=pushState?.stats;return shell(`<section class="card push-settings"><h2>Notifications sur cet appareil</h2><p>Reçois une alerte même lorsque l’application est fermée. Les détails restent dans ton espace connecté.</p>${unsupported?`<p class="notice">${e(unsupported)}</p>`:''}<p role="status">${e(pushError||(pushState?.enabled?'Cet appareil est inscrit aux notifications.':pushState?'Notifications désactivées sur cet appareil.':'Vérification de la configuration…'))}</p>${pushState&&!pushState.public_key?'<p>Configuration des notifications à terminer dans Supabase.</p>':''}<div class="head-actions">${!unsupported&&pushState?.public_key?(pushState.enabled?button('Désactiver cet appareil','push-disable')+button('Envoyer un test','push-test'):button('Activer les notifications','push-enable','',true)):''}${button('Vérifier l’état','push-status')}${pushState?button('Désactiver tous mes appareils','push-disable-all'):''}</div><p class="muted">L’affichage sur l’écran verrouillé dépend des autorisations et du mode Concentration de ton appareil. Une acceptation par le service d’envoi ne prouve pas la réception.</p>${stats?`<p>Envois des dernières 24 h${isQ()?' — organisation':' — mon compte'} : ${stats.pending} en attente · ${stats.accepted} acceptés par le service · ${stats.failed} en échec.</p>${pushState.queue_errors?'<p class="form-error">Des notifications n’ont pas pu être mises en file.</p>':''}${isQ()&&(stats.failed||pushState.queue_errors)?button('Reprendre les envois en échec','push-retry'):''}`:''}</section><section class="card"><h2>Dans votre espace</h2>${w.notifications.map(n=>`<div class="list-row"><div><h3>${e(n.title)}</h3><p>${e(n.body||'')} · ${e(dt(n.created_at))}</p>${n.entity_type==='intervention'&&w.interventions.some(i=>i.id===n.entity_id)?button('Ouvrir l’intervention','detail',n.entity_id):n.entity_type==='client_request'?'<button class="btn" data-route="requests">Voir les demandes</button>':''}</div>${!n.read_at?button('Marquer lu','read',n.id):'<span>Lu</span>'}</div>`).join('')||empty()}</section>`,'Notifications');}
function render(){if(!w)return login();const pages={home,planning,interventions,detail,clients,sites,team:people,requests,issues,docs,quality,logbook:logs,notifications,profile:()=>shell(`<section class="card"><h2>${e(w.profile.full_name)}</h2><p>${e(w.profile.role)}</p>${button('Changer mon mot de passe','password')}</section>`,'Mon compte')};if(!isQ()&&['clients','team','quality','logbook'].includes(route))route='home';app.innerHTML=(pages[route]||home)();if(!isQ()&&!isC()&&route==='detail'){const team=document.querySelector('.participation-section');if(team)document.querySelector('.v3-main').append(team);}document.querySelector('#mobile-route')?.addEventListener('change',ev=>navigate(ev.target.value));document.querySelector('#calendar-date')?.addEventListener('change',ev=>{calendar=ev.target.value||dayKey();render()});document.querySelector('#calendar-mode')?.addEventListener('change',ev=>{calendarMode=ev.target.value;render()});document.querySelector('#f-filter-site')?.addEventListener('change',ev=>{filterSite=ev.target.value;render()});loadImages();if(route==='notifications'&&!pushState&&!pushError&&!pushLoading)loadPushState();}
function navigate(next){closeNavigation();route=next;history.replaceState(null,'',location.pathname+location.search+'#'+next);render();window.scrollTo(0,0)}
async function loadImages(){for(const img of document.querySelectorAll('img[data-path]'))try{img.src=await api.file(img.dataset.path)}catch{img.alt='Photo indisponible — réessaie après actualisation';}}
const values=fd=>Object.fromEntries(fd.entries());
const datetime=v=>v?new Date(new Date(v).getTime()-new Date(v).getTimezoneOffset()*60000).toISOString().slice(0,16):'';
function interventionForm(id,request=null){const i=by(w.interventions,id)||(request?{site_id:request.site_id,title:request.title,service_type:categories[request.category]?request.category:'other',description:request.details||''}:{}),agents=w.people.filter(p=>['agent','team_lead'].includes(p.role)&&p.active),assigned=w.assignments.filter(a=>a.intervention_id===id).map(a=>a.agent_id);const key=crypto.randomUUID();modal(id?'Modifier l’intervention':request?'Accepter et planifier la demande':'Nouvelle intervention',(request?`<div class="notice"><strong>Demande client : ${e(request.title)}</strong><p>Date souhaitée : ${e(request.desired_date||'Non précisée')}. Choisis les horaires et les agents. L’acceptation sera confirmée à l’enregistrement ; fermer ce formulaire ne modifie pas la demande.</p><p>Les pièces jointes restent consultables depuis la demande d’origine.</p></div>`:'')+select('site_id','Client / site',w.sites.filter(s=>s.active).map(s=>({...s,name:(by(w.clients,s.client_id)?.name||'')+' · '+s.name})),i.site_id)+field('title','Intitulé',i.title,'text',true)+select('service_type','Type de prestation',opts(categories),i.service_type||'cleaning')+area('description','Description',i.description)+`<p>Horaires saisis dans le fuseau ${e(Intl.DateTimeFormat().resolvedOptions().timeZone)}. Planning affiché en heure de Paris.</p><div class="form-grid">`+field('starts_at','Début prévu',datetime(i.starts_at),'datetime-local',true)+field('ends_at','Fin prévue',datetime(i.ends_at),'datetime-local',true)+`</div><fieldset><legend>Agents affectés</legend>${agents.map(a=>`<label class="check-line"><input type="checkbox" name="agent_ids" value="${e(a.id)}" ${assigned.includes(a.id)?'checked':''}>${e(a.full_name)}</label>`).join('')||empty('Invite d’abord un agent.')}</fieldset>`+area('instructions','Consignes terrain',i.instructions)+area('internal_notes','Notes internes QG',i.internal_notes)+check('plan_visible','Rendre la prestation à venir visible au client',i.plan_visible)+(!id?select('template_id','Modèle de checklist',w.templates,'',true)+area('tasks_text','Tâches supplémentaires — une par ligne. Ajouter |photo ou |comment pour imposer une preuve.',request?request.title.replace(/[\r\n|]+/g,' '):''):'<p>La checklist et les preuves existantes sont conservées.</p>'),async fd=>{const p=values(fd);p.id=id||null;p.starts_at=isoDate(p.starts_at);p.ends_at=isoDate(p.ends_at);p.agent_ids=fd.getAll('agent_ids');p.plan_visible=fd.has('plan_visible');p.tasks=(p.tasks_text||'').split('\n').filter(s=>s.trim()).map((line,sort_order)=>{const [label,proof]=line.split('|');return {label:label.trim(),proof_required:proof?.trim()||'none',required:true,sort_order}});if(request){p.site_id=request.site_id;const result=await api.acceptRequest(request.id,p,key);selected=result.id;route='detail';toast(result.already_created?'Cette demande possède déjà une intervention. Ouverture de la fiche existante.':'Demande acceptée et intervention créée.');}else{await api.action('intervention',p,key);toast('Intervention enregistrée.');}});if(request){document.querySelector('#f-site_id').disabled=true;document.querySelector('#modal-form [type=submit]').textContent='Accepter et créer l’intervention';}}
function recordForm(kind,id){const c=by(kind==='client'?w.clients:w.sites,id)||{};const key=crypto.randomUUID();modal(`${id?'Modifier':'Créer'} ${kind==='client'?'un client':'un site'}`,(kind==='site'?select('client_id','Client',w.clients,c.client_id):'')+field('name','Nom',c.name,'text',true)+(kind==='client'?field('email','E-mail',c.email,'email')+field('phone','Téléphone',c.phone,'tel'):field('address','Adresse',c.address)+area('access_notes','Instructions d’accès privées',c.access_notes)+area('general_instructions','Consignes terrain',c.general_instructions))+area('contacts','Contacts utiles publiables',c.contacts)+(id?check('active','Actif — accès client autorisé',c.active):''),async fd=>{const p=values(fd);p.id=id||null;p.active=!id||fd.has('active');await api.action(kind,p,key);toast('Enregistrement confirmé.');});}
function photoForm(id,request=false){const taskList=w.tasks.filter(t=>t.intervention_id===id);const key=crypto.randomUUID();let url;modal('Ajouter une photo',field('file','Prendre ou choisir une photo','','file',true)+`<img id="photo-preview" class="preview" alt="Aperçu de la photo" hidden><p>JPEG, PNG ou WebP · 15 Mo maximum</p>`+(!request?select('category','Catégorie',opts({before:'Avant',after:'Après',issue:'Anomalie',general:'Autre preuve'}),'after')+select('task_id','Tâche associée',taskList.map(t=>({id:t.id,name:t.label})),'',true)+check('publishable','Autoriser cette photo avant/après dans le compte-rendu client',false):'')+area('caption','Légende publiable'),async fd=>{await api.upload(fd.get('file'),{intervention_id:request?null:id,request_id:request?id:null,task_id:fd.get('task_id')||null,category:fd.get('category')||'general',caption:fd.get('caption'),publishable:fd.has('publishable')},w.profile);if(url)URL.revokeObjectURL(url);toast('Photo enregistrée.');});const f=document.querySelector('#f-file');f.accept='image/jpeg,image/png,image/webp';f.setAttribute('capture','environment');f.onchange=()=>{if(url)URL.revokeObjectURL(url);if(f.files[0]){url=URL.createObjectURL(f.files[0]);const img=document.querySelector('#photo-preview');img.src=url;img.hidden=false}};}
async function report(id){const r=w.reports.find(r=>r.intervention_id===id);if(!r)throw new Error('Compte-rendu non publié.');const site=by(w.sites,r.payload.site_id),c=by(w.clients,site?.client_id);await showDocument('Compte-rendu client',clientReport(r,site,c));}
async function showDocument(title,html){modal(title,`<div class="report-actions">${button('Imprimer / enregistrer en PDF','print')}<p>Format A4 · Photos conservées en entier. Désactive les en-têtes et pieds de page du navigateur pour retirer l’URL.</p></div>${html}`);document.querySelector('dialog').classList.add('document-dialog');await loadImages();}

async function action(action,id,el){
 if(action==='menu'){openNavigation();return;}
 if(action==='show-tasks'){const target=document.querySelector('#mission-checklist');target?.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});return;}
 if(action==='close-menu'){closeNavigation();return;}
 if(action==='close'){if(!busy)closeModal();return;}
 if(action==='reset'){const email=document.querySelector('#f-email')?.value;if(!email)throw new Error('Saisis ton adresse e-mail.');await api.resetPassword(email);toast('Si cette adresse est reconnue, un lien lui sera envoyé.');return;}
 if(action==='logout'){await push.logout();await api.signOut();closeNavigation();w=null;closeModal();login();return;}
 if(action==='push-status'){await loadPushState();return;}
 if(action==='push-enable'){await push.enable(pushState?.public_key);await loadPushState();toast('Appareil inscrit. Envoie un test pour vérifier la réception.');return;}
 if(action==='push-disable'){await push.disable();await loadPushState();return;}
 if(action==='push-disable-all'){modal('Désactiver mes notifications', '<p>Les alertes seront désactivées sur tous les appareils de ton compte. Tu pourras les réactiver sur chaque appareil.</p>',async()=>{await push.disableAll();pushState=null;});return;}
 if(action==='push-test'){await push.test();toast('Test mis en file. Verrouille ton écran pour vérifier sa réception après traitement par le serveur.');await refresh();await loadPushState();return;}
 if(action==='push-retry'){await push.retry();await loadPushState();toast('Reprise demandée. Le résultat sera confirmé après traitement par le serveur.');return;}
 if(action==='refresh'){await refresh();return;}
 if(action==='today'){calendar=dayKey();render();return;}
 if(['prev-date','next-date'].includes(action)){const d=new Date(calendar+'T12:00Z');d.setUTCDate(d.getUTCDate()+(action==='next-date'?1:-1)*(calendarMode==='week'?7:1));calendar=d.toISOString().slice(0,10);render();return;}
 if(action==='detail'){selected=id;navigate('detail');return;}
 if(action==='site-history'){filterSite=id;navigate('interventions');return;}
 if(action==='client-sites'){const list=w.sites.filter(s=>s.client_id===id);modal('Sites et historique',list.map(s=>`<h3>${e(s.name)}</h3>${missionCards(w.interventions.filter(i=>i.site_id===s.id))}`).join('')||empty());return;}
 if(action==='agent-history'){modal('Affectations de '+name(id),missionCards(w.interventions.filter(i=>w.assignments.some(a=>a.intervention_id===i.id&&a.agent_id===id))));return;}
 if(['new-intervention','edit-intervention'].includes(action)){interventionForm(id);return;}
 if(['client','site'].includes(action)){recordForm(action,id);return;}
 if(action==='photo'){photoForm(id);return;}
 if(action==='request-upload'){photoForm(id,true);return;}
 if(action==='report'){await report(id);return;}
 if(action==='internal-report'){if(!isQ())throw new Error('Export interne réservé au QG.');w=await api.snapshot();await showDocument('Main courante interne',internalReport(w,id));return;}
 if(action==='print'){await Promise.all([...document.querySelectorAll('.print-report img')].map(img=>img.decode().catch(()=>{})));window.print();return;}
 if(['photo-view','request-photo','document-view'].includes(action)){const p=by(action==='document-view'?w.documents:action==='request-photo'?w.requestPhotos:w.photos,id);const url=await api.file(p.storage_path);modal(p.title||'Photo enregistrée',action==='document-view'?`<a class="btn primary" href="${e(url)}" target="_blank" rel="noopener noreferrer">Ouvrir le fichier sécurisé (lien valable 60 secondes)</a>`:`<img src="${e(url)}" class="preview" alt="Preuve photographique">`);return;}
 if(action==='start'){await api.action('start',{id});toast('Démarrage enregistré par le serveur.');await refresh();return;}
 if(action==='retry'){const result=await api.action('retry_publication',{id});toast(result.published?'Publication confirmée.':'La reprise a échoué ; l’erreur est conservée.',!result.published);await refresh();return;}
 if(action==='read'){await api.action('read_notification',{id});await refresh();return;}
 if(action==='password'){modal('Modifier mon mot de passe',field('current_password','Mot de passe actuel','','password',true)+field('password','Nouveau mot de passe (12 caractères minimum)','','password',true)+field('password_confirm','Confirmer le nouveau mot de passe','','password',true)+'<p>Le changement se fait directement ici, sans lien reçu par e-mail</p>',async fd=>{const password=fd.get('password');if(password.length<12||password.length>128)throw new Error('Choisis entre 12 et 128 caractères');if(password!==fd.get('password_confirm'))throw new Error('Les deux nouveaux mots de passe ne correspondent pas');await api.changePassword(fd.get('current_password'),password);toast('Mot de passe modifié');});document.querySelector('#f-current_password').autocomplete='current-password';for(const id of ['password','password_confirm']){const input=document.querySelector('#f-'+id);input.autocomplete='new-password';input.minLength=12;input.maxLength=128;}return;}

 const key=crypto.randomUUID();
 const submit=(kind,transform=values)=>async fd=>{const result=await api.action(kind,{...transform(fd),id:id||null},key);toast(result.published===false?'Enregistrement confirmé, mais publication en échec. Reprise nécessaire.':'Enregistrement confirmé.',result.published===false);return result;};
 if(action==='cancel'){modal('Annuler cette intervention',area('reason','Motif d’annulation'),submit('cancel'));return;}
 if(action==='finish'){const remaining=w.tasks.filter(t=>t.intervention_id===id&&t.required&&!t.completed).length;modal('Terminer ma participation',`<p>La fin sera horodatée par le serveur. Le suivi client sera actualisé automatiquement, sans attendre le QG.</p>${remaining?`<div class="notice warning">${remaining} tâche(s) obligatoire(s) non réalisée(s). Indique un motif précis.</div>`:''}`+area('reason','Observations finales internes / motif des tâches manquantes'),async fd=>{const r=await api.action('finish',{id,reason:fd.get('reason')},key);toast(r.published?'Fin enregistrée et compte-rendu publié.':'Fin enregistrée. Publication en échec : une reprise est disponible.',!r.published);});return;}
 if(action==='task'){const t=by(w.tasks,id);modal(t.completed?'Retirer la validation':'Valider la tâche',`<p>${e(t.label)}</p><p>Preuve requise : ${e(t.proof_required)}</p>`+area('comment','Commentaire',t.comment),submit('task',fd=>({completed:!t.completed,expected:t.completed,comment:fd.get('comment')})));return;}
 if(action==='note'){modal('Ajouter une observation',area('details','Observation')+check('publishable','Cette observation peut être publiée au client',false),submit('note',fd=>({details:fd.get('details'),publishable:fd.has('publishable')})));return;}
 if(action==='issue'){modal('Signaler un problème',field('title','Titre','','text',true)+select('category','Catégorie',opts({hygiene:'Anomalie nettoyage',damage:'Dégradation',equipment:'Matériel défectueux',impossible:'Intervention impossible',access:'Problème d’accès',other:'Autre'}))+select('priority','Priorité',opts({normal:'Normale',high:'Importante',urgent:'Urgente'}),'normal')+area('details','Description')+'<p>Ajoute une photo « Anomalie » dans la mission si nécessaire. Les signalements restent internes.</p>',submit('issue'));return;}
 if(action==='photo-permission'){const p=by(w.photos,id);modal('Corriger la visibilité',check('publishable','Autoriser pour le client (avant/après uniquement)',p.publishable)+area('reason','Motif de correction obligatoire'),submit('photo_permission',fd=>({publishable:fd.has('publishable'),reason:fd.get('reason')})));return;}
 if(action==='correct'){const i=by(w.interventions,id);modal('Correction exceptionnelle du compte-rendu',area('client_summary','Observations publiées',i.client_summary)+area('reason','Motif de correction obligatoire')+'<p>La correction crée une nouvelle révision du compte-rendu et une trace dans l’historique.</p>',submit('correct_report'));return;}
 if(action==='new-request'){modal('Demander une intervention',select('site_id','Établissement',w.sites)+field('title','Objet','','text',true)+select('category','Catégorie',opts(categories))+field('desired_date','Date souhaitée','','date')+area('details','Description')+'<p>Après enregistrement, tu peux joindre une photo à la demande.</p>',submit('request'));return;}
 if(action==='request-accept'){if(!isQ())throw new Error('Action QG uniquement');await refresh();const r=by(w.requests,id);if(!r)throw new Error('Demande introuvable');if(r.intervention_id){selected=r.intervention_id;navigate('detail');return;}if(!['new','in_progress'].includes(r.request_state))throw new Error('Cette demande est clôturée ou refusée.');interventionForm('',r);return;}
 if(action==='request-state'){const r=by(w.requests,id);modal('Traiter la demande',`<p>${e(r.title)}</p>`+select('request_state','État',opts({new:'Nouvelle',in_progress:'En traitement',resolved:'Traitée',refused:'Refusée',cancelled:'Annulée'}),r.request_state),submit('request_state'));return;}
 if(action==='issue-state'){modal('Suivre le signalement',select('status','État',opts({new:'Nouveau',in_progress:'En traitement',scheduled:'Planifié',resolved:'Résolu',closed:'Clôturé'}),by(w.issues,id)?.status),submit('issue_state'));return;}
 if(action==='profile-edit'){const p=by(w.people,id);modal('Gérer un compte',field('full_name','Nom complet',p.full_name,'text',true)+field('phone','Téléphone',p.phone,'tel')+check('active','Compte actif',p.active),submit('profile',fd=>({...values(fd),active:fd.has('active')})));return;}
 if(action==='create-user'){modal('Créer un accès',field('email','Adresse e-mail','','email',true)+field('full_name','Nom complet','','text',true)+select('role','Rôle',opts({agent:'Agent',team_lead:'Chef d’équipe terrain',client:'Client',...(w.profile.role==='qg_admin'?{qg_manager:'Responsable QG'}:{})}))+select('client_id','Client rattaché (obligatoire pour un contact client)',w.clients,'',true)+field('password','Mot de passe initial (12 caractères minimum)','','password',true)+field('password_confirm','Confirmer le mot de passe initial','','password',true)+'<p>Aucun e-mail d’invitation n’est envoyé. Transmets les identifiants à l’utilisateur ; il pourra changer son mot de passe dans Mon compte.</p>',async fd=>{const p=values(fd);if(p.password.length<12||p.password.length>128)throw new Error('Choisis entre 12 et 128 caractères');if(p.password!==p.password_confirm)throw new Error('Les mots de passe ne correspondent pas');if(p.role==='client'&&!p.client_id)throw new Error('Sélectionne le client rattaché');delete p.password_confirm;p.client_id=p.client_id||null;await api.createUser(p);toast('Accès créé — connexion possible avec le mot de passe choisi');});for(const id of ['password','password_confirm']){const input=document.querySelector('#f-'+id);input.autocomplete='new-password';input.minLength=12;input.maxLength=128;}return;}
 if(action==='invite'){modal('Inviter un utilisateur',field('email','Adresse e-mail','','email',true)+field('full_name','Nom complet','','text',true)+select('role','Rôle',opts({agent:'Agent',team_lead:'Chef d’équipe terrain',client:'Client',...(w.profile.role==='qg_admin'?{qg_manager:'Responsable QG'}:{})}))+select('client_id','Client rattaché (obligatoire pour un contact client)',w.clients,'',true),async fd=>{const p=values(fd);p.client_id=p.client_id||null;await api.invite(p);toast('Invitation envoyée.');});return;}
 if(action==='quality'){modal('Contrôle qualité',select('site_id','Site',w.sites)+select('result','Résultat',opts({conforme:'Conforme',a_ameliorer:'À améliorer',non_conforme:'Non conforme'}))+area('observations','Observations')+check('client_visible','Visible par le client'),submit('quality',fd=>({...values(fd),client_visible:fd.has('client_visible')})));return;}
 if(action==='document'){modal('Ajouter un document',field('title','Titre','','text',true)+select('site_id','Site obligatoire',w.sites)+select('visibility','Visibilité',opts({internal:'Interne QG',agent:'Équipe terrain',client:'Client'}))+field('file','Fichier PDF ou image','','file',true),async fd=>{await api.upload(fd.get('file'),{document:true,title:fd.get('title'),site_id:fd.get('site_id'),visibility:fd.get('visibility')},w.profile);toast('Document enregistré.');});document.querySelector('#f-file').accept='application/pdf,image/jpeg,image/png,image/webp';return;}
}
document.addEventListener('click',async ev=>{const el=ev.target.closest('[data-action],[data-route]');if(!el)return;if(el.dataset.route){closeModal();navigate(el.dataset.route);return;}if(el.dataset.action==='detail')closeModal();if(el.disabled)return;el.disabled=true;try{await action(el.dataset.action,el.dataset.id,el)}catch(err){toast(err.message,true)}finally{el.disabled=false}});
window.addEventListener('online',()=>{toast('Connexion rétablie.');refresh()});
window.addEventListener('offline',()=>toast('Hors connexion : aucune action n’est enregistrée localement.',true));
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&!document.querySelector('dialog'))refresh()});
setInterval(()=>{if(!document.hidden&&!document.querySelector('dialog')&&!busy)refresh()},30000);
async function boot(){if(!api.configured)return login();api.client.auth.onAuthStateChange(event=>{if(event==='PASSWORD_RECOVERY'){recovery=true;login()}if(event==='SIGNED_OUT'){closeNavigation();w=null;closeModal();login()}});try{const session=await api.session();if(recovery){if(!session){recovery=false;history.replaceState(null,'',location.pathname+(clientPortal?'?portal=client':'?portal=pro'));login('Le lien de réinitialisation n’a pas ouvert de session valide. Il peut être expiré ou déjà utilisé. Ouvre le lien du dernier e-mail reçu ; si le problème persiste, demande un nouveau lien lorsque la limite d’envoi le permet.');return;}login();return;}if(session)await enter();else login();}catch(err){login(err.message)}}
boot();
